#if DEBUG
import SwiftUI

/// Preview mode for the CI screenshots (`.github/workflows/ios.yml`):
/// launch argument `-vorschau <scene>`. Only exists in Debug builds - the
/// Release build for the .ipa contains none of it.
///
/// The messages are a real capture (fakester.app, 2026-10-04, a guest creates
/// a private lobby with "Featured", 5 songs). They go through
/// `Game.handleMessage`, exactly the path of real messages - so the screenshots
/// show the app as it looks in a game.
enum ScreenshotScene {
    static var sceneName: String? {
        let a: [String] = ProcessInfo.processInfo.arguments
        guard let i = a.firstIndex(of: "-scene"), i + 1 < a.count else { return nil }
        return a[i + 1]
    }

    @MainActor
    static func run(_ game: Game) {
        guard let s = sceneName else { return }
        let lobby: [String] = [Capture.lobby, Capture.chat]
        let activeRound: [String] = lobby + [Capture.activeRound]
        let reveal: [String] = activeRound + [Capture.lobbyInGame, Capture.outcome]
        switch s {
        case "lobby":
            game.replay(asPlayer: Capture.me, lobby)
        case "round":
            game.replay(asPlayer: Capture.me, activeRound)
        case "picked", "locked-in":
            game.replay(asPlayer: Capture.me, activeRound)
            game.answer = Capture.answer
            if s == "locked-in" { game.lockIn() }
        case "reveal":
            game.replay(asPlayer: Capture.me, reveal)
        case "game-over":
            game.replay(asPlayer: Capture.me, reveal + [Capture.end])
        default:
            break
        }
    }

    /// Shop and Style need `/profile`, which a screenshot run has no account
    /// for: the scenes use the test account's real profile (captured
    /// 2026-10-09: nothing bought yet, level 1), the catalog itself is public.
    static var sampleWardrobe: Wardrobe? {
        guard sceneName == "shop" || sceneName == "style" else { return nil }
        return try? JSONDecoder().decode(Wardrobe.self, from: Data(Capture.profile.utf8))
    }

    /// Quests and awards of the test account (captured 2026-10-09).
    static var sampleQuests: QuestOverview? {
        guard sceneName == "quests" || sceneName == "awards" else { return nil }
        return try? JSONDecoder().decode(QuestOverview.self, from: Data(Capture.quests.utf8))
    }

    static var sampleAwards: AchievementBoard? {
        guard sceneName == "quests" || sceneName == "awards" else { return nil }
        return try? JSONDecoder().decode(AchievementBoard.self, from: Data(Capture.awards.utf8))
    }

    /// The test account's real friend list: `{"friends":[]}`.
    static var sampleFriends: FriendList? {
        guard sceneName == "friends" else { return nil }
        return try? JSONDecoder().decode(FriendList.self, from: Data(#"{"friends":[]}"#.utf8))
    }

